{"implementation": "def solve(case):
    nodes = case['nodes']
    if len(nodes) <= 1:
        return {'mst_edges': [], 'total_weight': 0.0}
    core = case['core_distance']
    distances = case['distances']
    edges = []
    for u, v, d in distances:
        mr = max(core[u], core[v], d)
        if u < v:
            edges.append((mr, u, v))
        else:
            edges.append((mr, v, u))
    edges.sort(key=lambda x: (x[0], x[1], x[2]))
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True
    mst_edges = []
    total_weight = 0.0
    for mr, u, v in edges:
        if union(u, v):
            mst_edges.append([u, v, mr])
            total_weight += mr
            if len(mst_edges) == len(nodes) - 1:
                break
    else:
        raise ValueError('Graph is disconnected or insufficient edges')
    return {'mst_edges': mst_edges, 'total_weight': total_weight}"}
